eventHandler<Order>("ORDER_INSERT", transactional = true) {
      onValidate { event ->
        val details = event.details
        requireNotNull(details.instrumentId) { "Instrument ID is mandatory" }
        requireNotNull(details.clientCode) { "Client Code is mandatory" }
        requireNotNull(details.direction) { "Direction is mandatory" }
        requireNotNull(details.quantity) { "Quantity is mandatory" }
        require(details.quantity > java.math.BigDecimal.ZERO) { "Quantity must be greater than zero" }
        when (details.orderType) {
          Order.OrderType.LIMIT -> {
            requireNotNull(details.limitPrice) { "Limit Price is mandatory for LIMIT orders" }
            require(details.axeReference == null) { "Axe Reference must be absent for LIMIT orders" }
          }
          Order.OrderType.MARKET -> {
            require(details.limitPrice == null) { "Limit Price must be absent for MARKET orders" }
            require(details.axeReference == null) { "Axe Reference must be absent for MARKET orders" }
          }
          Order.OrderType.AXE_HIT -> {
            requireNotNull(details.axeReference) { "Axe Reference is mandatory for AXE_HIT orders" }
          }
          else -> return@onValidate nack("Unsupported order type")
        }
        entityDb.get(Instrument.ById(details.instrumentId)) ?: return@onValidate nack("Instrument not found")
        entityDb.get(Client.ByCode(details.clientCode)) ?: return@onValidate nack("Client not found")
        if (details.orderType == Order.OrderType.AXE_HIT) {
          val axeRef = requireNotNull(details.axeReference) { "Axe Reference is mandatory for AXE_HIT orders" }
          entityDb.get(Axe.ById(axeRef)) ?: return@onValidate nack("Referenced Axe not found")
        }
        ack()
      }
      onCommit { event ->
        val details = event.details
        val instrumentId = requireNotNull(details.instrumentId) { "Instrument ID is mandatory" }
        val clientCode = requireNotNull(details.clientCode) { "Client Code is mandatory" }
        val orderDirection = requireNotNull(details.direction) { "Direction is mandatory" }
        val orderQuantity = requireNotNull(details.quantity) { "Quantity is mandatory" }
        val submittingUser = event.userName
        val currentTime = now()
        val createdKeys = mutableListOf<Map<String, Any>>()

        when (details.orderType) {
          Order.OrderType.AXE_HIT -> {
            val axeRef = requireNotNull(details.axeReference) { "Axe Reference is mandatory for AXE_HIT orders" }
            val axe = entityDb.get(Axe.ById(axeRef)) ?: return@onCommit nack("Referenced Axe not found")

            // A client BUY hits the Axe's Ask side; a client SELL hits the Axe's Bid side
            val isBuy = orderDirection == Order.Direction.BUY
            val sidePrice = if (isBuy) axe.askPrice else axe.bidPrice
            val sideSize = if (isBuy) axe.askSize else axe.bidSize

            if (sidePrice == null || sideSize == null || orderQuantity > sideSize) {
              val rejectedOrder = Order {
                this.instrumentId = instrumentId
                this.clientCode = clientCode
                this.direction = orderDirection
                this.quantity = orderQuantity
                this.orderType = Order.OrderType.AXE_HIT
                this.axeReference = axeRef
                this.limitPrice = details.limitPrice
                this.filledQuantity = java.math.BigDecimal.ZERO
                this.status = Order.Status.REJECTED
                this.salesperson = submittingUser
                this.trader = details.trader
                this.createdAt = currentTime
                this.lastUpdated = currentTime
              }
              val insertedRejected = entityDb.insert(rejectedOrder)
              createdKeys.add(mapOf("ORDER_ID" to insertedRejected.record.orderId))
              return@onCommit ack(createdKeys)
            }

            val filledOrder = Order {
              this.instrumentId = instrumentId
              this.clientCode = clientCode
              this.direction = orderDirection
              this.quantity = orderQuantity
              this.orderType = Order.OrderType.AXE_HIT
              this.axeReference = axeRef
              this.limitPrice = details.limitPrice
              this.filledQuantity = orderQuantity
              this.status = Order.Status.FILLED
              this.salesperson = submittingUser
              this.trader = details.trader
              this.createdAt = currentTime
              this.lastUpdated = currentTime
            }
            val insertedOrder = entityDb.insert(filledOrder)
            val newOrderId = insertedOrder.record.orderId
            createdKeys.add(mapOf("ORDER_ID" to newOrderId))

            val newTrade = Trade {
              this.instrumentId = instrumentId
              this.clientCode = clientCode
              this.direction = Trade.Direction.valueOf(orderDirection.name)
              this.axeReference = axeRef
              this.orderId = newOrderId
              this.tradedPrice = sidePrice
              this.tradedQuantity = orderQuantity
              this.tradeDate = currentTime
              this.trader = details.trader
              this.salesPerson = submittingUser
              this.sourceProtocol = Trade.SourceProtocol.AXE_HIT
            }
            val insertedTrade = entityDb.insert(newTrade)
            val newTradeId = insertedTrade.record.tradeId
            createdKeys.add(mapOf("TRADE_ID" to newTradeId))

            val newFill = OrderFill {
              this.orderId = newOrderId
              this.fillPrice = sidePrice
              this.fillQuantity = orderQuantity
              this.filledAt = currentTime
              this.matchedAgainstAxe = axeRef
              this.matchedAgainstType = OrderFill.MatchedAgainstType.AXE
              this.tradeId = newTradeId
            }
            val insertedFill = entityDb.insert(newFill)
            createdKeys.add(mapOf("FILL_ID" to insertedFill.record.fillId))

            val remainingSize = sideSize.subtract(orderQuantity)
            val newRemaining = if (remainingSize < java.math.BigDecimal.ZERO) java.math.BigDecimal.ZERO else remainingSize
            val updatedAxe = axe.copy {
              if (isBuy) {
                askSize = newRemaining
              } else {
                bidSize = newRemaining
              }
              lastUpdated = currentTime
            }
            entityDb.modify(updatedAxe)

            ack(createdKeys)
          }
          Order.OrderType.LIMIT, Order.OrderType.MARKET -> {
            val isLimit = details.orderType == Order.OrderType.LIMIT
            val newOrderLimitPrice = details.limitPrice
            val oppositeDirection = if (orderDirection == Order.Direction.BUY) Order.Direction.SELL else Order.Direction.BUY

            val restingNew = entityDb.getRange(Order.ByInstrumentIdDirectionStatus(instrumentId, oppositeDirection, Order.Status.NEW)).toList()
            val restingPartial = entityDb.getRange(Order.ByInstrumentIdDirectionStatus(instrumentId, oppositeDirection, Order.Status.PARTIALLY_FILLED)).toList()

            val candidates = (restingNew + restingPartial)
              .filter { it.clientCode != clientCode }
              .filter { it.limitPrice != null }
              .filter { resting ->
                if (isLimit) {
                  val newPrice = requireNotNull(newOrderLimitPrice) { "Limit Price is mandatory for LIMIT orders" }
                  val restingPrice = requireNotNull(resting.limitPrice) { "Resting order missing limit price" }
                  // client BUY matches resting SELL priced <= newPrice; client SELL matches resting BUY priced >= newPrice
                  if (orderDirection == Order.Direction.BUY) restingPrice <= newPrice else restingPrice >= newPrice
                } else {
                  true
                }
              }

            // Price-time priority: best price first, then oldest.
            // For a BUY new order, best (lowest) resting sell price first; for SELL new order, best (highest) resting buy price first.
            val sortedCandidates = if (orderDirection == Order.Direction.BUY) {
              candidates.sortedWith(compareBy({ it.limitPrice }, { it.createdAt.millis }))
            } else {
              candidates.sortedWith(compareByDescending<Order> { it.limitPrice }.thenBy { it.createdAt.millis })
            }

            var remainingQty = orderQuantity
            var newFilledQty = java.math.BigDecimal.ZERO

            val newOrder = Order {
              this.instrumentId = instrumentId
              this.clientCode = clientCode
              this.direction = orderDirection
              this.quantity = orderQuantity
              this.orderType = details.orderType
              this.limitPrice = newOrderLimitPrice
              this.filledQuantity = java.math.BigDecimal.ZERO
              this.status = Order.Status.NEW
              this.salesperson = submittingUser
              this.trader = details.trader
              this.createdAt = currentTime
              this.lastUpdated = currentTime
            }
            val insertedNewOrder = entityDb.insert(newOrder)
            val newOrderId = insertedNewOrder.record.orderId

            for (resting in sortedCandidates) {
              if (remainingQty <= java.math.BigDecimal.ZERO) break
              val restingRemaining = resting.quantity.subtract(resting.filledQuantity)
              if (restingRemaining <= java.math.BigDecimal.ZERO) continue
              val matchQty = if (remainingQty < restingRemaining) remainingQty else restingRemaining
              val matchPrice = requireNotNull(resting.limitPrice) { "Resting order missing limit price" }

              val newTrade = Trade {
                this.instrumentId = instrumentId
                this.clientCode = clientCode
                this.direction = Trade.Direction.valueOf(orderDirection.name)
                this.orderId = newOrderId
                this.tradedPrice = matchPrice
                this.tradedQuantity = matchQty
                this.tradeDate = currentTime
                this.trader = details.trader
                this.salesPerson = submittingUser
                this.sourceProtocol = if (isLimit) Trade.SourceProtocol.LIMIT else Trade.SourceProtocol.MARKET
              }
              val insertedTrade = entityDb.insert(newTrade)
              val newTradeId = insertedTrade.record.tradeId
              createdKeys.add(mapOf("TRADE_ID" to newTradeId))

              val newFill = OrderFill {
                this.orderId = newOrderId
                this.fillPrice = matchPrice
                this.fillQuantity = matchQty
                this.filledAt = currentTime
                this.matchedAgainstOrder = resting.orderId
                this.matchedAgainstType = OrderFill.MatchedAgainstType.ORDER
                this.tradeId = newTradeId
              }
              val insertedFill = entityDb.insert(newFill)
              createdKeys.add(mapOf("FILL_ID" to insertedFill.record.fillId))

              val restingNewFilled = resting.filledQuantity.add(matchQty)
              val restingStatus = if (restingNewFilled >= resting.quantity) Order.Status.FILLED else Order.Status.PARTIALLY_FILLED
              val updatedResting = resting.copy {
                filledQuantity = restingNewFilled
                status = restingStatus
                lastUpdated = currentTime
              }
              entityDb.modify(updatedResting)

              remainingQty = remainingQty.subtract(matchQty)
              newFilledQty = newFilledQty.add(matchQty)
            }

            val finalStatus = if (newFilledQty >= orderQuantity) {
              Order.Status.FILLED
            } else if (isLimit) {
              if (newFilledQty > java.math.BigDecimal.ZERO) Order.Status.PARTIALLY_FILLED else Order.Status.NEW
            } else {
              if (newFilledQty > java.math.BigDecimal.ZERO) Order.Status.CANCELLED else Order.Status.REJECTED
            }

            val finalOrder = insertedNewOrder.record.copy {
              filledQuantity = newFilledQty
              status = finalStatus
              lastUpdated = currentTime
            }
            entityDb.modify(finalOrder)

            createdKeys.add(0, mapOf("ORDER_ID" to newOrderId))
            ack(createdKeys)
          }
          else -> nack("Unsupported order type")
        }
      }
    }

