              this.quantity = orderQuantity
              this.orderType = details.orderType
              this.limitPrice = newOrderLimitPrice
              this.filledQuantity = java.math.BigDecimal.ZERO
              this.status = Order.Status.NEW
              this.salesperson = submittingUser
              this.trader = details.trader
              this.createdAt = currentTime
              this.lastUpdated = currentTime
            }
            val insertedNewOrder = entityDb.insert(newOrder)
            val newOrderId = insertedNewOrder.record.orderId

            for (resting in sortedCandidates) {
              if (remainingQty <= java.math.BigDecimal.ZERO) break
              val restingRemaining = resting.quantity.subtract(resting.filledQuantity)
              if (restingRemaining <= java.math.BigDecimal.ZERO) continue
              val matchQty = if (remainingQty < restingRemaining) remainingQty else restingRemaining
              val matchPrice = requireNotNull(resting.limitPrice) { "Resting order missing limit price" }

              val newTrade = Trade {
                this.instrumentId = instrumentId
                this.clientCode = clientCode
                this.direction = Trade.Direction.valueOf(orderDirection.name)
                this.orderId = newOrderId
                this.tradedPrice = matchPrice
                this.tradedQuantity = matchQty
                this.tradeDate = currentTime
                this.trader = details.trader
                this.salesPerson = submittingUser
                this.sourceProtocol = if (isLimit) Trade.SourceProtocol.LIMIT else Trade.SourceProtocol.MARKET
              }
              val insertedTrade = entityDb.insert(newTrade)
              val newTradeId = insertedTrade.record.tradeId
              createdKeys.add(mapOf("TRADE_ID" to newTradeId))

              val newFill = OrderFill {
                this.orderId = newOrderId
                this.fillPrice = matchPrice
                this.fillQuantity = matchQty
                this.filledAt = currentTime
                this.matchedAgainstOrder = resting.orderId
                this.matchedAgainstType = OrderFill.MatchedAgainstType.ORDER
                this.tradeId = newTradeId
              }
              val insertedFill = entityDb.insert(newFill)
              createdKeys.add(mapOf("FILL_ID" to insertedFill.record.fillId))

              val restingNewFilled = resting.filledQuantity.add(matchQty)
              val restingStatus = if (restingNewFilled >= resting.quantity) Order.Status.FILLED else Order.Status.PARTIALLY_FILLED
              val updatedResting = resting.copy {
                filledQuantity = restingNewFilled
                status = restingStatus
                lastUpdated = currentTime
              }
              entityDb.modify(updatedResting)

              remainingQty = remainingQty.subtract(matchQty)
              newFilledQty = newFilledQty.add(matchQty)
            }

            val finalStatus = if (newFilledQty >= orderQuantity) {
              Order.Status.FILLED
            } else if (isLimit) {
              if (newFilledQty > java.math.BigDecimal.ZERO) Order.Status.PARTIALLY_FILLED else Order.Status.NEW
            } else {
              if (newFilledQty > java.math.BigDecimal.ZERO) Order.Status.CANCELLED else Order.Status.REJECTED
            }

            val finalOrder = insertedNewOrder.record.copy {
              filledQuantity = newFilledQty
              status = finalStatus
              lastUpdated = currentTime
            }
            entityDb.modify(finalOrder)

            createdKeys.add(0, mapOf("ORDER_ID" to newOrderId))
            ack(createdKeys)
          }
          else -> nack("Unsupported order type")
        }
      }
    }

